<?php
require_once __DIR__.'/config/app.php';require_login();$uid=(int)$_SESSION['user_id'];$id=(int)($_GET['id']??0);$message='';$s=mysqli_prepare($conn,'SELECT * FROM items WHERE id=? AND user_id=?');mysqli_stmt_bind_param($s,'ii',$id,$uid);mysqli_stmt_execute($s);$r=mysqli_stmt_get_result($s);if(mysqli_num_rows($r)!==1){set_flash('error','Report not found.');header('Location: my-reports.php');exit();}$item=mysqli_fetch_assoc($r);if($item['status']!=='active'){set_flash('error','Returned items cannot be edited.');header('Location: my-reports.php');exit();}
if($_SERVER['REQUEST_METHOD']==='POST'){$name=trim($_POST['item_name']??'');$cat=trim($_POST['category']??'');$loc=trim($_POST['location']??'');$date=$_POST['item_date']??'';$desc=trim($_POST['description']??'');$img=$item['image'];if($name===''||!valid_category($cat)||$loc===''||$date===''||$desc==='')$message='Please complete all required fields.';else{if(isset($_FILES['image'])&&$_FILES['image']['error']!==UPLOAD_ERR_NO_FILE){$up=upload_item_image($_FILES['image'],__DIR__.'/uploads');if(!$up['success'])$message=$up['message'];else{delete_item_image($img,__DIR__.'/uploads');$img=$up['filename'];}}if($message===''){$u=mysqli_prepare($conn,'UPDATE items SET item_name=?,category=?,description=?,location=?,item_date=?,image=? WHERE id=? AND user_id=?');mysqli_stmt_bind_param($u,'ssssssii',$name,$cat,$desc,$loc,$date,$img,$id,$uid);if(mysqli_stmt_execute($u)){set_flash('success','Report updated successfully.');header('Location: my-reports.php');exit();}$message='Could not update the report.';}}}
?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Edit Report - UniFind</title><link rel="stylesheet" href="css/style.css"></head><body><nav class="navbar"><a class="brand" href="dashboard.php">UniFind</a><div class="nav-actions"><a class="btn btn-small btn-secondary" href="my-reports.php">My Reports</a><a class="btn btn-small" href="logout.php">Logout</a></div></nav><main class="form-page"><div class="form-card"><span class="status-pill <?=$item['type']==='lost'?'lost-pill':'found-pill'?>"><?=strtoupper(e($item['type']))?></span><h1>Edit Report</h1><?php if($message):?><div class="alert alert-error"><?=e($message)?></div><?php endif;?><form method="post" enctype="multipart/form-data" class="form-stack"><div class="form-grid"><div><label>Item Name</label><input name="item_name" value="<?=e($_POST['item_name']??$item['item_name'])?>" required></div><div><label>Category</label><?php $cc=$_POST['category']??$item['category'];?><select name="category"><?php foreach(get_categories() as $c):?><option value="<?=e($c)?>" <?=$cc===$c?'selected':''?>><?=e($c)?></option><?php endforeach;?></select></div><div><label>Location</label><input name="location" value="<?=e($_POST['location']??$item['location'])?>" required></div><div><label>Date</label><input type="date" name="item_date" value="<?=e($_POST['item_date']??$item['item_date'])?>" required></div></div><div><label>Description</label><textarea name="description" required><?=e($_POST['description']??$item['description'])?></textarea></div><div><label>Replace Image</label><input type="file" name="image" accept=".jpg,.jpeg,.png,.webp"></div><button class="btn btn-block">Save Changes</button></form></div></main><script src="js/ui-effects.js"></script></body></html>